# Search translated-overlap common subsets between distinct original components; retain connected overlaps

def connected(ps):
 s=set(ps)
 if not s:return False
 st=[next(iter(s))];vis={st[0]}
 while st:
  r,c=st.pop()
  for q in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
   if q in s and q not in vis:vis.add(q);st.append(q)
 return len(vis)==len(s)
